"""Constants derived from the CMDB, exposed to Prometheus as recording rules.

`MemoryExhaustionPredicted` needs each service's memory limit. Generating it
from the CMDB keeps a single source of truth for that number.
"""

from __future__ import annotations

import yaml

from libs.core.cmdb import Cmdb

MEMORY_LIMIT_SERIES = "service:memory_limit:bytes"
MANAGED_SERIES = "service:managed:info"
MEBIBYTE = 1024 * 1024
HEADER = (
    "# GENERATED by `python -m tools.cli slo generate` from cmdb/services.yaml.\n"
    "# Do not edit: change the CMDB and regenerate. CI fails if this file is stale.\n"
)


def render_cmdb_rules(cmdb: Cmdb) -> str:
    """YAML rule file with constant series per service: managed marker and memory limit."""
    rules: list[dict[str, object]] = [
        {"record": MANAGED_SERIES, "expr": "vector(1)", "labels": {"service": name}}
        for name, service in sorted(cmdb.services.items())
        if service.managed
    ]
    rules += [
        {
            "record": MEMORY_LIMIT_SERIES,
            "expr": f"vector({service.memory_limit_mb * MEBIBYTE})",
            "labels": {"service": name},
        }
        for name, service in sorted(cmdb.services.items())
        if service.memory_limit_mb is not None
    ]
    body = yaml.safe_dump(
        {"groups": [{"name": "cmdb-constants", "rules": rules}]}, sort_keys=False, width=1000
    )
    return HEADER + body
